import { afterEach, beforeEach, describe, expect, test } from "bun:test";
import { mkdirSync, rmSync, unlinkSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { spawn } from "bun";

const BIN_PATH = join(import.meta.dir, "..", "..", "src", "bin.ts");

describe("CLI commands", () => {
  let testDir: string;

  beforeEach(() => {
    testDir = join(
      tmpdir(),
      `agentrack-cli-test-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    );
    mkdirSync(testDir, { recursive: true });
  });

  afterEach(() => {
    rmSync(testDir, { recursive: true, force: true });
  });

  async function runCLI(
    ...args: string[]
  ): Promise<{ stdout: string; stderr: string; exitCode: number }> {
    return runCLIWithEnv({}, ...args);
  }

  async function runCLIWithEnv(
    env: Record<string, string>,
    ...args: string[]
  ): Promise<{ stdout: string; stderr: string; exitCode: number }> {
    const proc = spawn({
      cmd: ["bun", "run", BIN_PATH, ...args],
      cwd: testDir,
      stdout: "pipe",
      stderr: "pipe",
      env: { ...process.env, ...env },
    });

    const stdout = await new Response(proc.stdout).text();
    const stderr = await new Response(proc.stderr).text();
    const exitCode = await proc.exited;

    return { stdout, stderr, exitCode };
  }

  describe("init", () => {
    test("agt init prints correct JSON to stdout", async () => {
      const { stdout, stderr, exitCode } = await runCLI("init");

      expect(exitCode).toBe(0);
      expect(stderr).toBe("");

      const result = JSON.parse(stdout.trim());
      expect(result.result).toBe("OK");
      expect(result.path).toContain(".agentrack");
    });

    test("agt init when already initialized prints ALREADY_INITIALIZED", async () => {
      await runCLI("init");
      const { stdout, exitCode } = await runCLI("init");

      expect(exitCode).toBe(0);

      const result = JSON.parse(stdout.trim());
      expect(result.result).toBe("ALREADY_INITIALIZED");
      expect(result.path).toContain(".agentrack");
    });
  });

  describe("create", () => {
    test("creates an issue and prints id to stdout", async () => {
      await runCLI("init");

      const { stdout, stderr, exitCode } = await runCLI("create", "My Issue");

      expect(exitCode).toBe(0);
      expect(stderr).toBe("");

      const result = JSON.parse(stdout.trim());
      expect(result.id).toBeDefined();
      expect(result.id).toHaveLength(10);
    });

    test("creates with all flags", async () => {
      await runCLI("init");

      const { stdout, exitCode } = await runCLI(
        "create",
        "Full Issue",
        "--description",
        "A description",
        "--assignee",
        "alice",
        "--tags",
        "bug,urgent",
        "--status",
        "todo",
        "--priority",
        "1",
      );

      expect(exitCode).toBe(0);

      const result = JSON.parse(stdout.trim());
      expect(result.id).toHaveLength(10);
    });

    test("prints error when not initialized", async () => {
      const { stdout, stderr, exitCode } = await runCLI("create", "Test");

      expect(exitCode).toBe(1);
      expect(stdout).toBe("");

      const result = JSON.parse(stderr.trim());
      expect(result.result).toBe("NOT_INITIALIZED");
    });

