    test("throws PULL_FAILED when pull fails", () => {
      const { local } = createGitRepoWithRemote();
      initWorktree(local);

      // Break the remote URL to cause pull failure
      execSync(`git remote set-url origin /nonexistent/path.git`, {
        cwd: local,
        stdio: "ignore",
