import { afterEach, describe, expect, test } from "bun:test";
import {
  existsSync,
  mkdirSync,
  readFileSync,
  rmSync,
  writeFileSync,
  unlinkSync,
  statSync,
} from "node:fs";
import { execSync } from "node:child_process";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import {
  WORKTREE_BRANCH,
  WORKTREE_DIR,
  detectInitScenario,
  initWorktree,
  initFreshWorktree,
  initJoinWorktree,
  isWorktreeInitialized,
  pullWorktree,
  pushWorktree,
} from "../../src/core/worktree";
import { AgentrackError } from "../../src/core/errors";
import { Tracker } from "../../src/core/tracker";

/**
 * Integration tests for the worktree module.
 *
 * These tests use real git operations in temp directories.
 * This gives the most reliable coverage of git worktree behavior.
 */
describe("worktree", () => {
  const tmpDirs: string[] = [];

  /** Create a temp directory that will be cleaned up in afterEach. */
  function createTempDir(): string {
    const dir = join(
      tmpdir(),
      `agentrack-wt-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    );
    mkdirSync(dir, { recursive: true });
    tmpDirs.push(dir);
    return dir;
  }

  /** Create a minimal git repo with one commit. */
  function createGitRepo(dir: string): string {
    execSync("git init", { cwd: dir, stdio: "ignore" });
    execSync('git config user.email "test@test.com"', { cwd: dir, stdio: "ignore" });
    execSync('git config user.name "Test"', { cwd: dir, stdio: "ignore" });
    writeFileSync(join(dir, "README.md"), "# Test\n");
    execSync("git add .", { cwd: dir, stdio: "ignore" });
    execSync('git commit -m "initial"', { cwd: dir, stdio: "ignore" });
    return dir;
  }

  /** Create a bare git repo (simulates a remote). */
  function createBareRepo(dir: string): string {
    mkdirSync(dir, { recursive: true });
    execSync("git init --bare", { cwd: dir, stdio: "ignore" });
    return dir;
  }

  /** Create a git repo with a bare remote (origin) configured. */
  function createGitRepoWithRemote(): { local: string; remote: string; base: string } {
    const base = createTempDir();
    const remote = join(base, "remote.git");
    const local = join(base, "local");
    createBareRepo(remote);
    mkdirSync(local);
    createGitRepo(local);
    execSync(`git remote add origin ${remote}`, { cwd: local, stdio: "ignore" });
    execSync("git push -u origin main", { cwd: local, stdio: "ignore" });
    return { local, remote, base };
  }

  /** Forcefully clean up worktree state in a directory. */
  function cleanupWorktree(dir: string): void {
    const wtPath = join(dir, WORKTREE_DIR);
    try {
      execSync(`git worktree remove -f "${wtPath}" 2>/dev/null || true`, {
        cwd: dir,
        stdio: "ignore",
      });
    } catch {}
    try {
      execSync("git worktree prune", { cwd: dir, stdio: "ignore" });
    } catch {}
  }

  afterEach(() => {
    for (const dir of tmpDirs) {
      cleanupWorktree(dir);
    }
    for (const dir of tmpDirs) {
      rmSync(dir, { recursive: true, force: true });
    }
    tmpDirs.length = 0;
  });

